create extension if not exists pgcrypto;
create type public.user_role as enum ('builder','supplier','admin');
create type public.claim_status as enum ('pending','approved','rejected');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,role public.user_role not null default 'builder',company_name text,full_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.supplier_profiles(id uuid primary key default gen_random_uuid(),owner_id uuid unique references auth.users(id) on delete set null,name text not null,slug text not null unique,trade_category text,city text,state text,website text,phone text,description text,service_area text,claimed boolean not null default false,verified boolean not null default false,is_public boolean not null default true,score integer check(score between 0 and 100),quality_score integer check(quality_score between 0 and 100),delivery_score integer check(delivery_score between 0 and 100),communication_score integer check(communication_score between 0 and 100),review_count integer not null default 0,source_name text,source_url text,external_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(source_name,external_id));
create table public.supplier_claims(id uuid primary key default gen_random_uuid(),supplier_id uuid not null references public.supplier_profiles(id) on delete cascade,claimant_user_id uuid not null references auth.users(id) on delete cascade,status public.claim_status not null default 'pending',verification_method text not null,full_name text not null,work_email text not null,phone text not null,company_role text not null check(company_role in ('owner','manager','sales_representative','operations')),reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(supplier_id,claimant_user_id));
create table public.saved_suppliers(id uuid primary key default gen_random_uuid(),builder_user_id uuid not null references auth.users(id) on delete cascade,supplier_profile_id uuid not null references public.supplier_profiles(id) on delete cascade,created_at timestamptz not null default now(),unique(builder_user_id,supplier_profile_id));
create table public.evaluations(id uuid primary key default gen_random_uuid(),builder_user_id uuid not null references auth.users(id) on delete cascade,supplier_profile_id uuid not null references public.supplier_profiles(id) on delete cascade,quality integer not null check(quality between 1 and 100),delivery integer not null check(delivery between 1 and 100),communication integer not null check(communication between 1 and 100),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(builder_user_id,supplier_profile_id));
create table public.reviews(id uuid primary key default gen_random_uuid(),evaluation_id uuid not null unique references public.evaluations(id) on delete cascade,supplier_profile_id uuid not null references public.supplier_profiles(id) on delete cascade,builder_user_id uuid not null references auth.users(id) on delete cascade,project_name text,project_type text,body text,verified boolean not null default true,is_public boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,type text not null,title text not null,body text,href text,read_at timestamptz,created_at timestamptz not null default now());
create table public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,stripe_customer_id text unique,stripe_subscription_id text unique,plan text not null default 'builder_free' check(plan in ('builder_free','builder_pro','builder_enterprise','supplier_free','supplier_verified','supplier_premium')),status text not null default 'free',current_period_end timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.processed_webhook_events(id text primary key,event_type text not null,processed_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,email,role,company_name,full_name) values(new.id,new.email,case when new.raw_user_meta_data->>'role'='supplier' then 'supplier'::public.user_role else 'builder'::public.user_role end,new.raw_user_meta_data->>'company_name',new.raw_user_meta_data->>'full_name');return new;end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_role(check_role public.user_role) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role=check_role);$$;
create or replace function public.refresh_supplier_scores() returns trigger language plpgsql security definer set search_path=public as $$begin update public.supplier_profiles s set quality_score=x.q,delivery_score=x.d,communication_score=x.c,score=round((x.q+x.d+x.c)/3.0),review_count=x.n,updated_at=now() from (select supplier_profile_id,round(avg(quality))::int q,round(avg(delivery))::int d,round(avg(communication))::int c,count(*)::int n from public.evaluations where supplier_profile_id=coalesce(new.supplier_profile_id,old.supplier_profile_id) group by supplier_profile_id)x where s.id=x.supplier_profile_id;return coalesce(new,old);end;$$;
create trigger evaluations_refresh_scores after insert or update or delete on public.evaluations for each row execute procedure public.refresh_supplier_scores();
alter table public.profiles enable row level security;alter table public.supplier_profiles enable row level security;alter table public.supplier_claims enable row level security;alter table public.saved_suppliers enable row level security;alter table public.evaluations enable row level security;alter table public.reviews enable row level security;alter table public.notifications enable row level security;alter table public.subscriptions enable row level security;alter table public.processed_webhook_events enable row level security;
create policy profiles_self_read on public.profiles for select using(id=auth.uid() or public.is_role('admin'));
create policy profiles_self_update on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
revoke update on public.profiles from authenticated;
grant update(full_name,company_name) on public.profiles to authenticated;
create policy suppliers_public_read on public.supplier_profiles for select using(is_public or owner_id=auth.uid() or public.is_role('admin'));
create policy suppliers_owner_update on public.supplier_profiles for update using(owner_id=auth.uid() and public.is_role('supplier')) with check(owner_id=auth.uid() and public.is_role('supplier'));
create policy claims_self_read on public.supplier_claims for select using(claimant_user_id=auth.uid() or public.is_role('admin'));
create policy claims_supplier_insert on public.supplier_claims for insert with check(claimant_user_id=auth.uid() and public.is_role('supplier'));
create policy saved_builder_all on public.saved_suppliers for all using(builder_user_id=auth.uid() and public.is_role('builder')) with check(builder_user_id=auth.uid() and public.is_role('builder'));
create policy evaluations_read_authenticated on public.evaluations for select using(auth.uid() is not null);
create policy evaluations_builder_insert on public.evaluations for insert with check(builder_user_id=auth.uid() and public.is_role('builder'));
create policy evaluations_builder_update on public.evaluations for update using(builder_user_id=auth.uid() and public.is_role('builder')) with check(builder_user_id=auth.uid() and public.is_role('builder'));
create policy reviews_public_read on public.reviews for select using(is_public or builder_user_id=auth.uid() or public.is_role('admin'));
create policy reviews_builder_insert on public.reviews for insert with check(builder_user_id=auth.uid() and public.is_role('builder'));
create policy notifications_self_read on public.notifications for select using(user_id=auth.uid());
create policy notifications_self_update on public.notifications for update using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy subscriptions_self_read on public.subscriptions for select using(user_id=auth.uid() or public.is_role('admin'));
revoke insert,update,delete on public.subscriptions from authenticated;
revoke all on public.processed_webhook_events from authenticated,anon;
create index supplier_search_idx on public.supplier_profiles using gin(to_tsvector('english',coalesce(name,'')||' '||coalesce(trade_category,'')||' '||coalesce(city,'')||' '||coalesce(service_area,'')));
create index evaluations_supplier_idx on public.evaluations(supplier_profile_id);create index reviews_supplier_idx on public.reviews(supplier_profile_id);create index notifications_user_idx on public.notifications(user_id,created_at desc);create index saved_builder_idx on public.saved_suppliers(builder_user_id);create index claims_status_idx on public.supplier_claims(status);
-- Promote your first admin after signup:
-- update public.profiles set role='admin' where email='you@yourdomain.com';
